import ballerina/io;

isolated class Stack {
    private int[] items = [];

    isolated function push(int v) {
        lock {
            self.items.push(v);
        }
    }

    isolated function top() returns int[] {
        lock {
            return self.items.length() > 0 ? [self.items[self.items.length() - 1]] : [];
        }
    }
}

public function main() {
    Stack s = new;
    io:println(s.top()); // @output []
    s.push(4);
    io:println(s.top()); // @output [4]
}

import ballerina/io;

client class C {
    resource function get users/[int id]() returns int {
        return id;
    }

    resource function get users/[string name]() returns int { // @error diverges from users/[int] at a non-singleton segment
        return name.length();
    }

    resource function get items/[int id]() returns int {
        return id;
    }

    resource function get items/[int... ids]() returns int { // @error diverges from items/[int] (member vs rest)
        return ids.length();
    }
}

public function main() {
    C c = new;
    int a = c->/users/["bob"];
    int b = c->/items/[1]/[2];
    io:println(a + b);
}

